'use strict';
const $ = selector => document.querySelector(selector);
const icon = name => `<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = value => {try {const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username?u.href:'';}catch{return '';}};
const core=BitcoinExplorer;
const compact=()=>innerWidth<=core.COMPACT_WIDTH;
function stored(key){try {const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value:[];}catch{return [];}}
const saved=new Set(stored('sun-saved'));
const state={merchants:[],category:'all',query:'',region:'',verification:'',payment:'',radius:null,area:null,limit:60,city:'',savedOnly:false,selected:null,user:null,sort:'featured',routeId:0,trailDismissed:false,trip:[],sheet:'half',originVersion:0};
const locator=BitcoinLocation.createLocator({geolocation:navigator.geolocation,permissions:navigator.permissions,secure:window.isSecureContext});
let map,clusters,tiles,routeLayer,userMarker,selectionMarker,toastTimer,markers=new Map(),markerKey='',afterOrigin=null,areaChoices=[],picking=false;
function notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{notify('Browser storage is unavailable. Saved for this visit.');}}
function group(m){if(/Coffee/.test(m.category))return 'coffee';if(/Restaurants|Bakeries|Bars|Groceries|Markets/.test(m.category))return 'food';if(/Shopping|Pets|Tech/.test(m.category))return 'shops';return 'other';}
function categoryIcon(m){return {coffee:'coffee',food:'food',shops:'shop',other:'spark'}[group(m)];}
function shortCategory(m){return m.category.replace('Coffee Shops & Cafés','Coffee & cafés').replace('Restaurants & Quick Bites','Food & drink');}
function featured(m){return m.id.startsWith('az-')?({'Echo Coffee':0,'Pita Cafe':1,'Scottsdale Burger Bar':2,'Stemistry':3,'The Buzzed Goat':4}[m.name]??10):10;}
function filtered(){return state.merchants.filter(m=>(state.category==='all'||group(m)===state.category)&&(!state.region||m.state===state.region)&&(!state.verification||m.verification?.type===state.verification)&&(!state.payment||m[state.payment]===true)&&(!state.city||m.city===state.city)&&(!state.savedOnly||saved.has(m.id))&&core.inside(m,state.area)&&(!state.radius||!state.user||core.distance(state.user,m)<=state.radius)&&(!state.query||`${m.name} ${m.city} ${m.state} ${m.address} ${m.category}`.toLowerCase().includes(state.query))).sort((a,b)=>state.sort==='distance'&&state.user?core.distance(state.user,a)-core.distance(state.user,b):state.sort==='name'?a.name.localeCompare(b.name):featured(a)-featured(b)||a.name.localeCompare(b.name));}
function badge(m){return `<span class="bitcoin-badge">${m.lightning?icon('zap'):'₿'}${m.lightning?'Lightning reported':m.onchain?'On-chain reported':'Bitcoin reported'}</span>`;}
function evidenceBadge(m){return `<span class="evidence-badge">${esc(BitcoinDirectory.evidence(m))}</span>`;}
function paymentStatus(m){const last=m.lastPayment,latest=m.latestPaymentReport;return `${last?`<span class="payment-success">Visitor paid ${esc(last.date)} · ${esc(last.rail==='onchain'?'on-chain':last.rail==='lightning'?'Lightning':'network unknown')}</span>`:''}${latest?.outcome==='failed'&&(!last||latest.date>=last.date)?`<span class="payment-caution">Reviewed payment difficulty · ${esc(latest.date)}</span>`:''}`;}
function merchantIcon(id,selected=false){return L.divIcon({className:'map-marker-shell'+(selected?' selected-map-marker':''),html:`<div class="bitcoin-marker ${selected?'selected':''}" style="width:30px;height:30px"><span>₿</span></div>`,iconSize:[30,30],iconAnchor:[15,27]});}
function mapFrame(){
  const cover=compact()?(picking?0:!$('#detail-panel').hidden?$('#detail-panel').offsetHeight:$('.explorer').classList.contains('map-view')?$('.sidebar').offsetHeight:0):0;
  return core.mapFrame(map.getSize().x,map.getSize().y,{compact:compact(),cover,detailWidth:!compact()&&!$('#detail-panel').hidden?$('#detail-panel').offsetWidth:0});
}
function fitMapBounds(bounds,maxZoom=14){const f=mapFrame();map.fitBounds(bounds,{paddingTopLeft:f.topLeft,paddingBottomRight:f.bottomRight,maxZoom,animate:false});}
function syncSelectedMarker(){
  const m=state.merchants.find(m=>m.id===state.selected);
  if(!m){if(selectionMarker){map.removeLayer(selectionMarker);selectionMarker=null;}return;}
  if(selectionMarker)selectionMarker.setLatLng([m.lat,m.lon]).setIcon(merchantIcon(m.id,true));
  else selectionMarker=L.marker([m.lat,m.lon],{icon:merchantIcon(m.id,true),zIndexOffset:1000,interactive:false,keyboard:false,alt:`Selected: ${m.name}`}).addTo(map);
}
function focusSelected(){
  const m=state.merchants.find(m=>m.id===state.selected);if(!m||!map)return;
  const offset=map.getSize().divideBy(2).subtract(L.point(mapFrame().center));
  const center=map.unproject(map.project([m.lat,m.lon],map.getZoom()).add(offset),map.getZoom());
  map.panTo(center,{animate:false});
}
let layoutTimer;
function refreshMapLayout(){clearTimeout(layoutTimer);layoutTimer=setTimeout(()=>{if(!map||!$('#map').clientWidth||!$('#map').clientHeight)return;map.invalidateSize({pan:false});if(routeLayer)fitMapBounds(routeLayer.getBounds(),15);else if(state.selected)focusSelected();else fitResults();},100);}
function render(){
  const rows=filtered();
  $('#result-count').textContent=`${rows.length.toLocaleString()} ${state.savedOnly?'saved ':''}place${rows.length===1?'':'s'}`;
  $('#sheet-count').textContent=`${rows.length.toLocaleString()} places`;
  $('#saved-count').textContent=saved.size;$('#saved-nav').setAttribute('aria-label',`Saved places (${saved.size})`);$('#map-count').textContent=`${rows.length.toLocaleString()} places`;
  $('#map-region').textContent=state.area?'SELECTED MAP AREA':state.region?BitcoinGeo.states[state.region].name.toUpperCase():'UNITED STATES';
  $('#clear-area').hidden=!state.area;$('#search-area').textContent=state.area?'Search this area again':'Search this area';
  $('#saved-nav').classList.toggle('active',state.savedOnly);$('#explore-nav').classList.toggle('active',!state.savedOnly);
  $('#trail-card').hidden=state.trailDismissed||Boolean(state.selected)||Boolean(state.region&&state.region!=='AZ')||Boolean(state.area)||Boolean(state.user)||!['Echo Coffee','Pita Cafe','Scottsdale Burger Bar'].every(name=>state.merchants.some(m=>m.name===name));
  const cards=rows.slice(0,state.limit);
  if(state.selected&&!cards.some(m=>m.id===state.selected)){const selected=rows.find(m=>m.id===state.selected);if(selected)cards.unshift(selected);}
  $('#business-list').innerHTML=cards.length?cards.map(m=>`<article class="business-card ${state.selected===m.id?'selected':''}" data-id="${esc(m.id)}"><div class="card-art">${icon(categoryIcon(m))}</div><div class="card-content">${featured(m)<3?'<div class="card-eyebrow">Featured in Bitcoin Magazine</div>':''}<h3><button aria-label="View ${esc(m.name)}">${esc(m.name)}</button></h3><p class="card-address">${esc(m.address||m.city)}</p><div class="card-tags">${badge(m)}${state.user?`<span>· ${core.distance(state.user,m).toFixed(1)} mi</span>`:''}</div><div class="card-evidence">${evidenceBadge(m)} · ${esc(m.state)}</div>${paymentStatus(m)}<button class="card-trip" data-trip="${esc(m.id)}" aria-pressed="${state.trip.includes(m.id)}">${state.trip.includes(m.id)?'✓ On your trail':'+ Add to trail'}</button></div><button class="save-button ${saved.has(m.id)?'saved':''}" data-save="${esc(m.id)}" aria-label="${saved.has(m.id)?'Unsave':'Save'} ${esc(m.name)}" aria-pressed="${saved.has(m.id)}">${icon('heart')}</button></article>`).join('')+(rows.length>state.limit?`<button id="show-more" class="secondary-button">Show ${Math.min(60,rows.length-state.limit)} more</button>`:''):`<div class="empty">${icon('search')}<strong>No places match this selection.</strong><p>Try a wider map area, a larger distance, or fewer filters.</p><button id="reset-filters">Reset filters →</button></div>`;
  const nextKey=rows.map(m=>m.id).join(',');
  if(clusters&&nextKey!==markerKey){markerKey=nextKey;clusters.clearLayers();markers.clear();const batch=rows.map(m=>{const marker=L.marker([m.lat,m.lon],{icon:merchantIcon(m.id),title:m.name,alt:m.name,keyboard:true});marker.bindTooltip(esc(m.name),{direction:'top',offset:[0,-25]});marker.on('click',()=>selectPlace(m.id));marker.on('mouseover',()=>highlightCard(m.id,true));marker.on('mouseout',()=>highlightCard(m.id,false));markers.set(m.id,marker);return marker;});clusters.addLayers(batch);}
  if(map)syncSelectedMarker();renderTrip();
}
function highlightCard(id,active){for(const el of document.querySelectorAll('[data-id]'))if(el.dataset.id===id)el.classList.toggle('hovered',active);}
function highlightPin(id,active){const marker=markers.get(id);marker?._icon?.querySelector('.bitcoin-marker')?.classList.toggle('highlighted',active);if(marker?._icon){if(active)marker.openTooltip();else marker.closeTooltip();}}
function fitResults(){if(!map)return;let rows=filtered();if(!state.region&&!state.area&&rows.some(m=>m.state!=='AK'&&m.state!=='HI'))rows=rows.filter(m=>m.state!=='AK'&&m.state!=='HI');if(rows.length)fitMapBounds(rows.map(m=>[m.lat,m.lon]));else notify('No places match these filters. Try a larger area or fewer filters.');}
function clearRoute(){state.routeId++;if(routeLayer){map.removeLayer(routeLayer);routeLayer=null;}}
function closeDetail(returnFocus=false){const priorId=state.selected;clearRoute();state.selected=null;$('.explorer').classList.remove('detail-open');$('#detail-panel').hidden=true;if(!location.hash.startsWith('#trip='))history.replaceState(null,'',location.pathname+location.search);render();if(returnFocus){const target=compact()?$('#mobile-toggle'):document.querySelector(`[data-id="${priorId}"] h3 button`)||$('#search');target.focus({preventScroll:true});}}
function updateFilters(fit=true){state.limit=60;closeDetail();if(fit&&!state.area)fitResults();}
function savePlace(id){saved.has(id)?saved.delete(id):saved.add(id);persist('sun-saved',[...saved]);render();if(state.selected===id)renderDetail(state.merchants.find(m=>m.id===id));}
function renderDetail(m){
  if(!m)return;
  const notes=m.paymentNotes||(m.verification?.type==='merchant-confirmed'?m.verification.summary:'');
  $('#detail-panel').hidden=false;$('#trail-card').hidden=true;$('.explorer').classList.add('detail-open');
  $('#detail-panel').innerHTML=`<button class="dismiss" data-action="close" aria-label="Close business details">×</button><span class="detail-category">${esc(shortCategory(m))}</span><h2>${esc(m.name)}</h2>${badge(m)} ${evidenceBadge(m)}<p>${esc(m.address||m.city)}</p>${paymentStatus(m)}${notes?`<div class="payment-details"><strong>Before you visit</strong><p>${esc(notes)}</p></div>`:''}<div class="detail-links">${safeUrl(m.website)?`<a href="${esc(safeUrl(m.website))}" target="_blank" rel="noopener">Website ↗</a>`:''}${m.phone?`<a href="tel:${esc(m.phone.replace(/[^+\d]/g,''))}">Call ↗</a>`:''}${m.osmId?`<a href="https://btcmap.org/merchant/${esc(m.osmId)}" target="_blank" rel="noopener">BTC Map ↗</a>`:''}</div><button class="primary-button" data-action="directions">${icon('route')}Preview route</button><p class="route-status" id="route-status" role="status" hidden></p><a class="secondary-button" href="${esc(core.mapsUrl([m],state.user))}" target="_blank" rel="noopener">Directions in Google Maps ↗</a><button class="secondary-button" data-action="trip">${state.trip.includes(m.id)?'✓ On your trail':'+ Add to your trail'}</button><button class="secondary-button" data-action="save">${saved.has(m.id)?'Saved to your places':'Save this place'}</button><button class="secondary-button" data-action="share">Copy place link</button><div class="payment-feedback"><strong>Paid here recently?</strong><p>Share your visit for maintainer review.</p><a data-community="correction" data-outcome="paid" data-listing-id="${esc(m.id)}" href="${esc(BitcoinCommunity.issueUrl('correction',m))}">I paid here ✓</a><a data-community="correction" data-outcome="failed" data-listing-id="${esc(m.id)}" href="${esc(BitcoinCommunity.issueUrl('correction',m))}">Payment didn’t work</a></div><a class="detail-report" data-community="correction" data-listing-id="${esc(m.id)}" href="${esc(BitcoinCommunity.issueUrl('correction',m))}">Report incorrect listing ↗</a><p class="footnote">${esc(BitcoinDirectory.dateLabel(m))}. <a href="${esc(safeUrl(BitcoinDirectory.source(m)))}" target="_blank" rel="noopener">Read evidence ↗</a>${m.lastPayment?`<br><a href="${esc(safeUrl(m.lastPayment.reviewIssue))}" target="_blank" rel="noopener">Read reviewed visitor payment report ↗</a>`:''}${m.verification?.summary&&m.verification.summary!==notes?`<br>${esc(m.verification.summary)}`:''}<br>Payment reports are visitor claims reviewed by the maintainer. Confirm payment before a special trip.</p>`;
}
function selectPlace(id,move=true){
  const m=state.merchants.find(m=>m.id===id);if(!m)return;if(!filtered().some(row=>row.id===id))reset();clearRoute();state.selected=id;history.replaceState(null,'',`#${id}`);render();renderDetail(m);
  if(compact()){showMobileMap(true);$('.explorer').scrollIntoView({block:'start',behavior:'auto'});}map.invalidateSize({pan:false});
  if(move){map.setView([m.lat,m.lon],Math.max(15,map.getZoom()),{animate:false});focusSelected();}
  if(!compact()){const card=document.querySelector(`[data-id="${id}"]`);if(card)$('#business-list').scrollTop=card.offsetTop-$('#business-list').offsetTop;}
  $('#detail-panel [data-action="close"]').focus({preventScroll:true});
}
function setOrigin(point){state.user=point;state.originVersion++;if(userMarker)map.removeLayer(userMarker);userMarker=L.marker([point.lat,point.lon],{icon:L.divIcon({className:'user-marker',iconSize:[18,18]})}).addTo(map).bindTooltip(esc(point.type==='gps'?'Device location':point.label));$('#origin-title').textContent=point.type==='gps'?'Your starting location is ready.':`Start: ${point.label}`;$('#origin-note').textContent=point.type==='area'?'Approximate area based on mapped businesses. Choose a map point for a more specific start.':point.type==='pin'?'Using your chosen map point. Change it any time.':point.accuracy>1000?`Approximate device location (about ${Math.round(point.accuracy/1000)} km accuracy). You can set a more specific map point.`:'Device location is used only for this visit. Shared trails never include it.';$('#use-location').textContent='Refresh my location';render();if(state.selected)renderDetail(state.merchants.find(m=>m.id===state.selected));}
async function locate(refresh=false){if(!map)throw new Error('The directory is still loading. Please try again in a moment.');if(state.user&&!refresh)return state.user;const version=state.originVersion;const point=await locator.locate({refresh});if(version===state.originVersion)setOrigin(point);return state.user||point;}
async function withOrigin(action,refresh=false){try{await action(await locate(refresh));}catch(error){openLocation(error.message,action);}}
function openLocation(message='',action=null){afterOrigin=action;$('#location-help').textContent=message||'Use your device location, choose an approximate area, or set a starting point on the map.';$('#location-search').value='';$('#location-results').innerHTML='';areaChoices=[];$('#location-dialog').showModal();}
function chooseOrigin(point){const action=afterOrigin;afterOrigin=null;setOrigin(point);$('#location-dialog').close();picking=false;$('#map-pick').hidden=true;$('.explorer').classList.remove('picking');if(action)Promise.resolve(action(point)).catch(error=>notify(error.message));}
function nearby(){state.region='';state.city='';state.area=null;state.radius=Number($('#radius').value)||25;state.sort='distance';$('#state').value='';$('#radius').value=String(state.radius);$('#sort').value='distance';fillCities();updateFilters(false);const rows=filtered().slice(0,8);if(rows.length)fitMapBounds([state.user,...rows].map(m=>[m.lat,m.lon]));else map.setView([state.user.lat,state.user.lon],11);notify(rows.length?'Nearby places are ready.':'No matches nearby. Try a larger distance or fewer filters.');}
async function drawRoute(stops,statusEl){clearRoute();const requestId=state.routeId;statusEl.hidden=false;statusEl.textContent='Finding your orange route…';try{const response=await fetch(`https://router.project-osrm.org/route/v1/driving/${stops.map(m=>`${m.lon},${m.lat}`).join(';')}?overview=full&geometries=geojson`,{signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error();const data=await response.json();if(data.code!=='Ok'||!data.routes?.[0])throw Error();if(requestId!==state.routeId)return;const r=data.routes[0];routeLayer=L.geoJSON(r.geometry,{style:{color:'#f7931a',weight:5,opacity:1,className:'route-line'}}).addTo(map);fitMapBounds(routeLayer.getBounds(),15);statusEl.textContent=`${(r.distance/1609.344).toFixed(1)} miles · about ${Math.max(1,Math.round(r.duration/60))} min driving · no live traffic${state.user?.type==='area'?' · starting from an approximate area':''}`;}catch{if(requestId===state.routeId)statusEl.textContent='Road preview could not load. You can still navigate using Google Maps.';}}
function showMobileMap(show){$('.explorer').classList.toggle('map-view',show);$('#mobile-toggle').innerHTML=icon(show?'shop':'pin')+(show?'Full list':'Show map');if(map)refreshMapLayout();}
function setSheet(snap){if(snap!=='full'){$('.explorer').classList.remove('filters-open');$('#sheet-filters').setAttribute('aria-expanded','false');}state.sheet=snap;$('.explorer').dataset.sheet=snap;$('#sheet-handle').setAttribute('aria-expanded',String(snap==='full'));$('#sheet-handle').setAttribute('aria-label',snap==='full'?'Collapse places panel':'Expand places panel');}
function setTheme(){const dark=document.documentElement.dataset.theme==='dark';$('#theme-toggle').innerHTML=icon(dark?'sun':'moon');$('#theme-toggle').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`);$('meta[name="theme-color"]').content=dark?'#151a17':'#f7f7f2';if(map&&!tiles){let loaded=0,errors=0;tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);tiles.on('tileload',()=>{loaded++;$('#tile-notice').hidden=true;});tiles.on('tileerror',()=>{errors++;if(!loaded&&errors>3)$('#tile-notice').hidden=false;});}}
function tripRows(){return state.trip.map(id=>state.merchants.find(m=>m.id===id)).filter(Boolean);}
function renderTrip(){const rows=tripRows();$('#trip-count').textContent=rows.length;$('#trip-stops').innerHTML=rows.length?rows.map((m,i)=>`<li><span class="trip-number">${i+1}</span><div><button data-trip-select="${esc(m.id)}">${esc(m.name)}</button><small>${esc(m.city)}, ${esc(m.state)}</small></div><button data-reorder="${i}" data-delta="-1" ${i===0?'disabled':''} aria-label="Move ${esc(m.name)} earlier">↑</button><button data-reorder="${i}" data-delta="1" ${i===rows.length-1?'disabled':''} aria-label="Move ${esc(m.name)} later">↓</button><button data-remove="${esc(m.id)}" aria-label="Remove ${esc(m.name)}">×</button></li>`).join(''):'<li class="empty">Add a place from a business card to start your trail.</li>';for(const id of ['trip-preview','trip-share','trip-clear'])$('#'+id).disabled=!rows.length;const nav=$('#trip-navigate');nav.hidden=!rows.length;if(rows.length)nav.href=core.mapsUrl(rows,state.user);}
function toggleTrip(id){if(state.trip.includes(id))state.trip=state.trip.filter(value=>value!==id);else if(state.trip.length<core.MAX_STOPS)state.trip.push(id);else{notify('Your trail can include up to four stops. Remove a stop to add another.');return;}clearRoute();$('#trip-status').hidden=true;persist('sun-trip',state.trip);if(location.hash.startsWith('#trip='))history.replaceState(null,'',state.trip.length?core.shareTrip(state.trip,state.merchants,location.href):location.pathname);render();if(state.selected)renderDetail(state.merchants.find(m=>m.id===state.selected));}
function openTrip(){renderTrip();$('#trip-panel').hidden=false;$('#trip-panel').scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
async function copy(text,message){try{await navigator.clipboard.writeText(text);notify(message);}catch{window.prompt('Copy this link:',text);}}
function fillCities(){const cities=[...new Set(state.merchants.filter(m=>!state.region||m.state===state.region).map(m=>m.city).filter(Boolean))].sort();$('#city').innerHTML='<option value="">All cities</option>'+cities.map(c=>`<option>${esc(c)}</option>`).join('');$('#city').value=state.city;}
function reset(){Object.assign(state,{savedOnly:false,query:'',region:'',verification:'',payment:'',radius:null,area:null,city:'',category:'all'});for(const id of ['search','state','verification','payment-filter','radius','city'])$('#'+id).value='';fillCities();document.querySelectorAll('[data-category]').forEach(el=>el.classList.toggle('active',el.dataset.category==='all'));updateFilters();}
async function start(){setTheme();setSheet(compact()&&innerHeight<500?'peek':'half');try{const res=await fetch('merchants.json');if(!res.ok)throw Error();const data=await res.json();state.merchants=data.merchants;BitcoinCommunity.setMerchants(state.merchants);state.trip=core.tripIds(stored('sun-trip'),state.merchants);const shared=core.parseTrip(location.hash,state.merchants);if(location.hash.startsWith('#trip=')){state.trip=shared;if(!shared.length)notify('This trail has no current listings. Build a new trail below.');}$('#total-count').textContent=state.merchants.length.toLocaleString();$('#state').innerHTML='<option value="">All 50 states + DC</option>'+Object.entries(BitcoinGeo.states).sort((a,b)=>a[1].name.localeCompare(b[1].name)).map(([code,s])=>`<option value="${code}">${esc(s.name)} · ${state.merchants.filter(m=>m.state===code).length}</option>`).join('');const requested=new URLSearchParams(location.search).get('state');if(BitcoinGeo.states[requested])state.region=requested;const linked=state.merchants.find(m=>m.id===location.hash.slice(1));if(linked)state.region=linked.state;$('#state').value=state.region;fillCities();if(!window.L)throw Error();map=L.map('map',{zoomControl:false,preferCanvas:true,maxZoom:19,minZoom:3}).setView([39,-98],4);clusters=L.markerClusterGroup({showCoverageOnHover:false,spiderfyOnMaxZoom:true,maxClusterRadius:38,iconCreateFunction:c=>L.divIcon({html:String(c.getChildCount()),className:'cluster-icon',iconSize:[37,37]})}).addTo(map);setTheme();if('ResizeObserver' in window)new ResizeObserver(refreshMapLayout).observe($('#map'));else window.addEventListener('resize',refreshMapLayout);render();fitResults();if(linked)selectPlace(linked.id);if(shared.length){openTrip();fitMapBounds(tripRows().map(m=>[m.lat,m.lon]));}const version=state.originVersion;if(await locator.permission()==='granted'&&version===state.originVersion){try{await locate();if(!location.hash&&!state.region)nearby();}catch{ $('#origin-note').textContent='Choose a city or ZIP, or set a map point to explore nearby.';}}}catch(error){$('#result-count').textContent='Unable to load the map';$('#business-list').innerHTML='<div class="empty">We couldn’t load the directory. Check your connection and refresh.<button id="reload">Try again →</button></div>';console.error(error);}}
$('#theme-toggle').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('sun-theme',document.documentElement.dataset.theme);}catch{}setTheme();};
let searchTimer;$('#search').oninput=e=>{state.query=e.target.value.trim().toLowerCase();clearTimeout(searchTimer);searchTimer=setTimeout(()=>updateFilters(),180);};
$('#state').onchange=e=>{state.region=e.target.value;state.city='';state.area=null;state.radius=null;$('#radius').value='';fillCities();history.replaceState(null,'',location.pathname+(state.region?'?state='+state.region:''));updateFilters();};
$('#verification').onchange=e=>{state.verification=e.target.value;updateFilters();};
$('#payment-filter').onchange=e=>{state.payment=e.target.value;updateFilters();};
$('#city').onchange=e=>{state.city=e.target.value;state.area=null;updateFilters();};
$('#radius').onchange=e=>{state.radius=Number(e.target.value)||null;if(state.radius&&!state.user){withOrigin(()=>nearby());return;}updateFilters();};
$('.category-filters').onclick=e=>{const button=e.target.closest('[data-category]');if(!button)return;state.category=button.dataset.category;document.querySelectorAll('[data-category]').forEach(el=>el.classList.toggle('active',el===button));updateFilters();};
$('#sort').onchange=e=>{state.sort=e.target.value;if(state.sort==='distance'&&!state.user){withOrigin(()=>{state.sort='distance';render();});return;}render();};
$('#business-list').onclick=e=>{if(e.target.closest('#show-more')){const top=$('#business-list').scrollTop;state.limit+=60;render();$('#business-list').scrollTop=top;return;}if(e.target.closest('#reset-filters')){reset();return;}if(e.target.closest('#reload')){location.reload();return;}const save=e.target.closest('[data-save]'),trip=e.target.closest('[data-trip]');if(save){savePlace(save.dataset.save);return;}if(trip){toggleTrip(trip.dataset.trip);return;}const card=e.target.closest('[data-id]');if(card)selectPlace(card.dataset.id);};
$('#business-list').onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-id]')){e.preventDefault();selectPlace(e.target.dataset.id);}};
for(const [event,active] of [['mouseover',true],['mouseout',false],['focusin',true],['focusout',false]])$('#business-list').addEventListener(event,e=>{const card=e.target.closest('[data-id]');if(card)highlightPin(card.dataset.id,active);});
$('#saved-nav').onclick=()=>{state.savedOnly=true;closeDetail();fitResults();showMobileMap(false);};$('#explore-nav').onclick=()=>{state.savedOnly=false;render();showMobileMap(false);};
$('#story-nav').onclick=()=>$('#story-dialog').showModal();$('#story-dialog .dialog-close').onclick=()=>$('#story-dialog').close();
for(const id of ['near-me','use-location'])$('#'+id).onclick=async()=>{const b=$('#'+id);b.disabled=true;b.setAttribute('aria-busy','true');$('#origin-note').textContent='Finding your starting location…';try{await withOrigin(()=>nearby(),id==='use-location');}finally{b.disabled=false;b.removeAttribute('aria-busy');}};
$('#choose-location').onclick=()=>openLocation('',()=>nearby());
$('#location-close').onclick=()=>$('#location-dialog').close();$('#location-dialog').addEventListener('close',()=>{if(!picking)afterOrigin=null;});
$('#location-retry').onclick=async()=>{const b=$('#location-retry');b.disabled=true;$('#location-help').textContent='Trying your device location…';try{const point=await locator.locate({refresh:true});chooseOrigin(point);}catch(error){$('#location-help').textContent=error.message;}finally{b.disabled=false;}};
$('#location-search').oninput=e=>{areaChoices=core.areas(state.merchants,e.target.value);$('#location-results').innerHTML=areaChoices.length?areaChoices.map((p,i)=>`<button data-area="${i}"><strong>${esc(p.label)}</strong><span>${p.count} mapped places · approximate area</span></button>`).join(''):e.target.value.trim().length>=2?'<p>No matching area in this directory. Try a nearby city or set a map point.</p>':'';};
$('#location-results').onclick=e=>{const button=e.target.closest('[data-area]');if(button&&areaChoices[button.dataset.area])chooseOrigin(areaChoices[button.dataset.area]);};
$('#pick-map-point').onclick=()=>{if(!map){$('#location-help').textContent='The map is still loading. Try again in a moment.';return;}picking=true;$('#location-dialog').close();clearRoute();$('#detail-panel').hidden=true;$('.explorer').classList.remove('detail-open');$('#map-pick').hidden=false;$('.explorer').classList.add('picking');showMobileMap(true);setSheet('peek');$('.explorer').scrollIntoView({block:'start'});};
$('#confirm-map-point').onclick=()=>{const p=map.getCenter();chooseOrigin({lat:p.lat,lon:((p.lng+180)%360+360)%360-180,type:'pin',label:'Chosen map point'});};
$('#cancel-map-point').onclick=()=>{picking=false;afterOrigin=null;$('#map-pick').hidden=true;$('.explorer').classList.remove('picking');if(state.selected)renderDetail(state.merchants.find(m=>m.id===state.selected));};
$('#search-area').onclick=()=>{if(!map)return;const b=map.getBounds();state.area=core.bounds(b.getSouth(),b.getNorth(),b.getWest(),b.getEast());state.limit=60;updateFilters(false);setSheet('half');};
$('#clear-area').onclick=()=>{state.area=null;updateFilters(false);};
$('#zoom-in').onclick=()=>map?.zoomIn();$('#zoom-out').onclick=()=>map?.zoomOut();$('#fit-map').onclick=()=>fitResults();
$('#surprise').onclick=()=>{const rows=filtered();if(rows.length)selectPlace(rows[Math.floor(Math.random()*rows.length)].id);else notify('Choose a wider area or fewer filters first.');};
$('#dismiss-trail').onclick=()=>{state.trailDismissed=true;$('#trail-card').hidden=true;};
$('#trail-button').onclick=()=>{const stops=['Echo Coffee','Pita Cafe','Scottsdale Burger Bar'].map(name=>state.merchants.find(m=>m.name===name&&m.state==='AZ'));if(stops.some(m=>!m)){notify('The Scottsdale trail is being updated. Build your own trail instead.');openTrip();return;}state.trip=stops.map(m=>m.id);persist('sun-trip',state.trip);render();openTrip();};
$('#detail-panel').onclick=e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='close'){closeDetail(true);return;}const m=state.merchants.find(m=>m.id===state.selected);if(!m)return;if(action==='save')savePlace(m.id);if(action==='trip')toggleTrip(m.id);if(action==='share'){const url=new URL(location.href);url.search='';url.hash=m.id;copy(url.href,'Place link copied.');}if(action==='directions'){withOrigin(async origin=>{if(state.selected!==m.id)return;await drawRoute([origin,m],$('#route-status'));});}};
$('#trip-open').onclick=openTrip;$('#trip-close').onclick=()=>$('#trip-panel').hidden=true;
$('#trip-stops').onclick=e=>{const remove=e.target.closest('[data-remove]'),reorder=e.target.closest('[data-reorder]'),select=e.target.closest('[data-trip-select]');if(remove)toggleTrip(remove.dataset.remove);if(select)selectPlace(select.dataset.tripSelect);if(reorder){const index=Number(reorder.dataset.reorder),next=index+Number(reorder.dataset.delta);if(next>=0&&next<state.trip.length){[state.trip[index],state.trip[next]]=[state.trip[next],state.trip[index]];persist('sun-trip',state.trip);clearRoute();$('#trip-status').hidden=true;renderTrip();if(location.hash.startsWith('#trip='))history.replaceState(null,'',core.shareTrip(state.trip,state.merchants,location.href));}}};
$('#trip-preview').onclick=async()=>{const rows=tripRows();if(!rows.length)return;closeDetail();showMobileMap(true);setSheet('peek');const stops=state.user?[state.user,...rows]:rows;if(stops.length===1){map.setView([rows[0].lat,rows[0].lon],14);$('#trip-status').hidden=false;$('#trip-status').textContent='Add a second stop or choose a starting point to preview a route.';return;}await drawRoute(stops,$('#trip-status'));$('.explorer').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});notify($('#trip-status').textContent);};
$('#trip-share').onclick=()=>copy(core.shareTrip(state.trip,state.merchants,location.href),'Trail link copied. Your starting location is not included.');
$('#trip-clear').onclick=()=>{state.trip=[];persist('sun-trip',[]);clearRoute();$('#trip-status').hidden=true;if(location.hash.startsWith('#trip='))history.replaceState(null,'',location.pathname);render();};
$('#mobile-toggle').onclick=()=>{closeDetail();showMobileMap(!$('.explorer').classList.contains('map-view'));};
$('#sheet-filters').onclick=()=>{const open=$('.explorer').classList.toggle('filters-open');$('#sheet-filters').setAttribute('aria-expanded',String(open));setSheet(open?'full':'half');};
let suppressSheetClickUntil=0;$('#sheet-handle').onclick=()=>{if(performance.now()<suppressSheetClickUntil)return;setSheet(state.sheet==='peek'?'half':state.sheet==='half'?'full':'peek');};
$('#sheet-handle').onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();setSheet(e.key==='ArrowUp'?'full':'peek');}};
let sheetDrag=null;$('#sheet-handle').onpointerdown=e=>{sheetDrag={y:e.clientY,height:$('.sidebar').getBoundingClientRect().height};e.currentTarget.setPointerCapture(e.pointerId);};
$('#sheet-handle').onpointermove=e=>{if(!sheetDrag)return;const h=Math.max(100,Math.min($('.explorer').clientHeight*.86,sheetDrag.height+sheetDrag.y-e.clientY));$('.sidebar').style.setProperty('--drag-height',`${h}px`);};
$('#sheet-handle').onpointerup=e=>{if(!sheetDrag)return;const delta=sheetDrag.y-e.clientY;$('.sidebar').style.removeProperty('--drag-height');if(Math.abs(delta)>20){setSheet(delta>0?'full':'peek');suppressSheetClickUntil=performance.now()+400;e.preventDefault();}sheetDrag=null;};
$('#sheet-handle').onpointercancel=()=>{sheetDrag=null;$('.sidebar').style.removeProperty('--drag-height');};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();showMobileMap(false);$('#search').focus();}if(e.key==='Escape'&&state.selected&&!document.querySelector('dialog[open]'))closeDetail(true);});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#trip=')){state.trip=core.parseTrip(location.hash,state.merchants);render();openTrip();}else if(BitcoinGeo.validId(location.hash.slice(1)))selectPlace(location.hash.slice(1));});
start();
